1	/**
2	 * Importer for the cfo.ai business plan.
3	 *
4	 * What cfo.ai offers (checked 2026-10-12, docs.cfo.ai/llms.txt, cfo.ai/skill.md,
5	 * docs.cfo.ai/integrations/mcp-server.md): no REST API and no API key. Programmatic access is a
6	 * remote MCP server (https://api.cfo.ai/mcp, Streamable HTTP) authorized by browser OAuth for an
7	 * approved account; its tools read the Model (`inspect_table_blocks` `read`, `inspect_pages`,
8	 * `inspect_scenarios`, …). The docs describe no file export (CSV/XLSX/PDF/JSON) of a Model; Pages
9	 * are shared as read-only links. So Notary never calls cfo.ai itself: the user reads the plan out
10	 * of cfo.ai (over MCP from their own agent, or from Ari) into the small, documented CSV below, and
11	 * this module parses it. Only the parsed values, the file's base name and its sha256 are kept, so
12	 * anyone holding the file can check the import.
13	 *
14	 * Format "notary-cfo-plan-csv/1" (header row required, RFC 4180 quoting, `#` lines are comments):
15	 *
16	 *   section,key,label,period,value,unit,detail
17	 *   meta,workspace,,,Notary,,              workspace | page | scenario | exported_at | share_url | currency
18	 *   tier,team,Team,,49,USD/contract/month,Up to 5 monitored contracts
19	 *   tier_feature,team,Certificates and revocations,,,,
20	 *   series,revenue,Revenue,2026-11,1200,USD,
21	 *   figure,runway_months,Runway,,14,months,At current burn
22	 *
23	 * Values are taken exactly as exported; nothing is rounded, scaled or filled in.
24	 */
25	import { readFileSync } from "node:fs";
26	import { basename } from "node:path";
27	import { sha256Hex } from "../bundle/hash.js";
28	import { CfoPlanSchema, type CfoPlan, type CfoPlanFigure, type CfoPlanSeries, type CfoPlanTier } from "../schema/economics.js";
29	
30	export const CFO_PLAN_FORMAT = "notary-cfo-plan-csv/1" as const;
31	export const CFO_PLAN_HEADER = ["section", "key", "label", "period", "value", "unit", "detail"] as const;
32	const META_KEYS = ["workspace", "page", "scenario", "exported_at", "share_url", "currency"] as const;
33	type MetaKey = (typeof META_KEYS)[number];
34	
35	export class CfoImportError extends Error {
36	  constructor(message: string) {
37	    super(message);
38	    this.name = "CfoImportError";
39	  }
40	}
41	
42	/** RFC 4180 rows: commas, double-quoted fields with "" escapes, CRLF or LF line ends. */
43	export function parseCsv(text: string): string[][] {
44	  const rows: string[][] = [];
45	  let row: string[] = [];
46	  let field = "";
47	  let quoted = false;
48	  let i = 0;
49	  const src = text.replace(/^﻿/, "");
50	  while (i < src.length) {
51	    const c = src[i]!;
52	    if (quoted) {
53	      if (c === '"') {
54	        if (src[i + 1] === '"') {
55	          field += '"';
56	          i += 2;
57	          continue;
58	        }
59	        quoted = false;
60	        i++;
61	        continue;
62	      }
63	      field += c;
64	      i++;
65	      continue;
66	    }
67	    if (c === '"' && field === "") {
68	      quoted = true;
69	      i++;
70	    } else if (c === ",") {
71	      row.push(field);
72	      field = "";
73	      i++;
74	    } else if (c === "\r" || c === "\n") {
75	      row.push(field);
76	      rows.push(row);
77	      row = [];
78	      field = "";
79	      i += c === "\r" && src[i + 1] === "\n" ? 2 : 1;
80	    } else {
81	      field += c;
82	      i++;
83	    }
84	  }
85	  if (quoted) throw new CfoImportError("unterminated quoted field");
86	  if (field !== "" || row.length) {
87	    row.push(field);
88	    rows.push(row);
89	  }
90	  return rows;
91	}
92	
93	function num(raw: string, where: string): number {
94	  const t = raw.trim();
95	  // Plain decimal numbers only: no thousands separators, currency signs or percent, so a value is
96	  // never reinterpreted on the way in.
97	  if (!/^-?\d+(\.\d+)?([eE][-+]?\d+)?$/.test(t)) throw new CfoImportError(`${where}: value ${JSON.stringify(raw)} is not a plain number`);
98	  return Number(t);
99	}
100	
101	const opt = (s: string): string | null => (s.trim() === "" ? null : s.trim());
102	
103	/** "USD/contract/month" -> currency USD, period "contract/month". */
104	function priceUnit(unit: string, where: string): { currency: string; period: string } {
105	  const m = /^([A-Z]{3})\/(.+)$/.exec(unit.trim());
106	  if (!m) throw new CfoImportError(`${where}: tier unit must look like CUR/period (e.g. USD/contract/month), got ${JSON.stringify(unit)}`);
107	  return { currency: m[1]!, period: m[2]!.trim() };
108	}
109	
110	export interface CfoImportInput {
111	  text: string;
112	  /** Base name recorded in the plan (never the full path). */
113	  file: string;
114	  importedAt: string;
115	  /** sha256 of the file's bytes; defaults to sha256 of `text`. */
116	  fileSha256?: string;
117	}
118	
119	/** Parse a notary-cfo-plan-csv/1 export into a validated plan. Throws CfoImportError on any problem. */
120	export function parseCfoPlanCsv(input: CfoImportInput): CfoPlan {
121	  const rows = parseCsv(input.text)
122	    .map((cells, i) => ({ cells, line: i + 1 }))
123	    .filter(({ cells }) => !(cells.length === 1 && cells[0]!.trim() === "") && !cells[0]!.trimStart().startsWith("#"));
124	  if (!rows.length) throw new CfoImportError("the file is empty");
125	  const header = rows[0]!.cells.map((h) => h.trim().toLowerCase());
126	  if (header.join(",") !== CFO_PLAN_HEADER.join(","))
127	    throw new CfoImportError(`line ${rows[0]!.line}: header must be exactly "${CFO_PLAN_HEADER.join(",")}" (got "${header.join(",")}")`);
128	
129	  const meta: Partial<Record<MetaKey, string>> = {};
130	  const tiers: CfoPlanTier[] = [];
131	  const features: { key: string; label: string; where: string }[] = [];
132	  const series = new Map<string, CfoPlanSeries>();
133	  const figures: CfoPlanFigure[] = [];
134	
135	  for (const { cells, line } of rows.slice(1)) {
136	    const where = `line ${line}`;
137	    if (cells.length !== CFO_PLAN_HEADER.length)
138	      throw new CfoImportError(`${where}: expected ${CFO_PLAN_HEADER.length} columns, got ${cells.length}`);
139	    const [section, key, label, period, value, unit, detail] = cells.map((c) => c.trim()) as [string, string, string, string, string, string, string];
140	    const s = section.toLowerCase();
141	    if (!key) throw new CfoImportError(`${where}: key is empty`);
142	    switch (s) {
143	      case "meta": {
144	        if (!(META_KEYS as readonly string[]).includes(key)) throw new CfoImportError(`${where}: unknown meta key ${JSON.stringify(key)} (expected ${META_KEYS.join(", ")})`);
145	        if (meta[key as MetaKey] !== undefined) throw new CfoImportError(`${where}: meta ${key} is given twice`);
146	        meta[key as MetaKey] = value;
147	        break;
148	      }
149	      case "tier": {
150	        if (tiers.some((t) => t.key === key)) throw new CfoImportError(`${where}: tier ${key} is given twice`);
151	        const { currency, period: per } = priceUnit(unit, where);
152	        tiers.push({ key, name: label || key, price: num(value, where), currency, period: per, description: opt(detail), features: [] });
153	        break;
154	      }
155	      case "tier_feature":
156	        if (!label) throw new CfoImportError(`${where}: tier_feature needs the feature text in label`);
157	        features.push({ key, label, where });
158	        break;
159	      case "series": {
160	        if (!period) throw new CfoImportError(`${where}: series ${key} row has no period`);
161	        const existing = series.get(key);
162	        const point = { period, value: num(value, where) };
163	        if (!existing) series.set(key, { key, label: label || key, unit, points: [point] });
164	        else {
165	          if (existing.unit !== unit) throw new CfoImportError(`${where}: series ${key} changes unit (${existing.unit} -> ${unit})`);
166	          if (existing.points.some((p) => p.period === period)) throw new CfoImportError(`${where}: series ${key} repeats period ${period}`);
167	          existing.points.push(point);
168	        }
169	        break;
170	      }
171	      case "figure":
172	        if (figures.some((f) => f.key === key)) throw new CfoImportError(`${where}: figure ${key} is given twice`);
173	        figures.push({ key, label: label || key, value: num(value, where), unit, detail: opt(detail) });
174	        break;
175	      default:
176	        throw new CfoImportError(`${where}: unknown section ${JSON.stringify(section)} (expected meta, tier, tier_feature, series, figure)`);
177	    }
178	  }
179	  for (const f of features) {
180	    const tier = tiers.find((t) => t.key === f.key);
181	    if (!tier) throw new CfoImportError(`${f.where}: tier_feature names tier ${f.key}, which has no tier row`);
182	    tier.features.push(f.label);
183	  }
184	  if (!tiers.length && !series.size && !figures.length) throw new CfoImportError("the file has no tier, series or figure rows");
185	
186	  const currency = opt(meta.currency ?? "");
187	  if (currency !== null && !/^[A-Z]{3}$/.test(currency)) throw new CfoImportError(`meta currency must be a 3-letter code, got ${JSON.stringify(currency)}`);
188	  const shareUrl = opt(meta.share_url ?? "");
189	  if (shareUrl !== null && !/^https:\/\/[^\s]+$/.test(shareUrl)) throw new CfoImportError("meta share_url must be an https URL");
190	
191	  const plan = {
192	    source: {
193	      tool: "cfo.ai" as const,
194	      format: CFO_PLAN_FORMAT,
195	      file: basename(input.file),
196	      fileSha256: input.fileSha256 ?? sha256Hex(input.text),
197	      importedAt: input.importedAt,
198	      workspace: opt(meta.workspace ?? ""),
199	      page: opt(meta.page ?? ""),
200	      scenario: opt(meta.scenario ?? ""),
201	      exportedAt: opt(meta.exported_at ?? ""),
202	      shareUrl,
203	    },
204	    currency,
205	    tiers,
206	    series: [...series.values()],
207	    figures,
208	  };
209	  const parsed = CfoPlanSchema.safeParse(plan);
210	  if (!parsed.success) throw new CfoImportError(`the plan does not fit the economics schema: ${parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}`);
211	  return parsed.data;
212	}
213	
214	/** Read and parse an export file from disk (bytes hashed as read). */
215	export function importCfoPlanFile(path: string, importedAt: string): CfoPlan {
216	  const bytes = readFileSync(path);
217	  return parseCfoPlanCsv({ text: bytes.toString("utf8"), file: path, importedAt, fileSha256: sha256Hex(new Uint8Array(bytes)) });
218	}
