1	/**
2	 * `notary economics`: writes packages/web/public/economics.json (schema/economics.ts) and
3	 * docs/BUSINESS.md from
4	 *   - REAL bundles: packages/core/runs/<dir>/<runId>.json (export/collect.ts rules) and the
5	 *     published packages/web/public/bundles/<runId>.json; sample/fixture and drift bundles are
6	 *     listed under `skipped`, never used
7	 *   - public/certificates/report.json (real only) for cost per certificate
8	 *   - the cfo.ai plan: `--cfo-import <file>` parses a fresh export; otherwise the plan already in
9	 *     economics.json is kept if that file still verifies (schema + content hash)
10	 * The output is a pure function of those inputs (the import timestamp is part of the plan).
11	 */
12	import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
13	import { basename, dirname, join } from "node:path";
14	import { fileURLToPath } from "node:url";
15	import { canonicalJson, sha256Hex, verifyBundle } from "../bundle/hash.js";
16	import { collectBundles, isDriftReplay } from "../export/collect.js";
17	import { CertificateReportSchema, type CertificateReport } from "../schema/certificate.js";
18	import {
19	  ECONOMICS_GENERATED_BY,
20	  EconomicsBodyCheckedSchema,
21	  EconomicsFileSchema,
22	  type CfoPlan,
23	  type EconomicsBody,
24	  type EconomicsFile,
25	} from "../schema/economics.js";
26	import type { RunBundle } from "../schema/index.js";
27	import { importCfoPlanFile } from "./cfo-import.js";
28	import { combine, computeEconomics } from "./compute.js";
29	import { renderBusinessMd } from "./business-md.js";
30	import { renderCfoInputsCsv } from "./cfo-inputs.js";
31	
32	export { parseCfoPlanCsv, importCfoPlanFile, parseCsv, CfoImportError, CFO_PLAN_FORMAT, CFO_PLAN_HEADER } from "./cfo-import.js";
33	export { computeEconomics, combine, economicsRun } from "./compute.js";
34	export { renderBusinessMd } from "./business-md.js";
35	export { renderCfoInputsCsv, CFO_INPUTS_COLUMNS } from "./cfo-inputs.js";
36	
37	const REPO_ROOT = fileURLToPath(new URL("../../../../", import.meta.url));
38	
39	export const ECONOMICS_PATHS = {
40	  runsDir: fileURLToPath(new URL("../../runs/", import.meta.url)),
41	  webBundlesDir: join(REPO_ROOT, "packages", "web", "public", "bundles"),
42	  certificatesReport: join(REPO_ROOT, "packages", "web", "public", "certificates", "report.json"),
43	  economicsJson: join(REPO_ROOT, "packages", "web", "public", "economics.json"),
44	  businessMd: join(REPO_ROOT, "docs", "BUSINESS.md"),
45	  cfoInputsCsv: join(REPO_ROOT, "export", "cfo-inputs.csv"),
46	};
47	
48	/** sha256 hex of canonicalJson(file without contentHash). Same rule as run bundles. */
49	export function economicsHash(body: EconomicsBody | EconomicsFile): string {
50	  const { contentHash: _ignored, ...rest } = body as EconomicsFile;
51	  return sha256Hex(canonicalJson(rest));
52	}
53	
54	/** Validate the body and stamp its content hash. */
55	export function finalizeEconomics(body: EconomicsBody): EconomicsFile {
56	  const parsed = EconomicsBodyCheckedSchema.parse(body);
57	  return EconomicsFileSchema.parse({ ...parsed, contentHash: economicsHash(parsed) });
58	}
59	
60	export type EconomicsVerify = { ok: true; file: EconomicsFile } | { ok: false; error: string };
61	
62	export function verifyEconomics(raw: unknown): EconomicsVerify {
63	  const parsed = EconomicsFileSchema.safeParse(raw);
64	  if (!parsed.success) return { ok: false, error: `economics.json fails its schema: ${parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}` };
65	  const actual = economicsHash(parsed.data);
66	  if (actual !== parsed.data.contentHash) return { ok: false, error: `economics.json content hash mismatch: recorded ${parsed.data.contentHash}, computed ${actual}` };
67	  return { ok: true, file: parsed.data };
68	}
69	
70	interface Source {
71	  bundle: RunBundle;
72	  file: string;
73	}
74	
75	/** Top-level <runId>.json files of the published dashboard dir (never fixture/, never timelines). */
76	function publishedBundles(dir: string): { bundles: Source[]; skipped: { file: string; reason: string }[] } {
77	  const out = { bundles: [] as Source[], skipped: [] as { file: string; reason: string }[] };
78	  if (!existsSync(dir)) return out;
79	  for (const name of readdirSync(dir).sort()) {
80	    if (!name.endsWith(".json") || name === "index.json" || name.endsWith(".timeline.json")) continue;
81	    const file = `web/public/bundles/${name}`;
82	    let raw: unknown;
83	    try {
84	      raw = JSON.parse(readFileSync(join(dir, name), "utf8"));
85	    } catch {
86	      out.skipped.push({ file, reason: "unreadable JSON" });
87	      continue;
88	    }
89	    const v = verifyBundle(raw);
90	    if (!v.ok) {
91	      out.skipped.push({ file, reason: v.reason === "hash" ? "content hash mismatch (tampered or edited after writing)" : "fails the bundle schema" });
92	      continue;
93	    }
94	    const b = v.bundle;
95	    if (b.sample || b.kind === "sample" || b.variant === "sample") {
96	      out.skipped.push({ file, reason: "SAMPLE/fixture bundle — never a source of results" });
97	      continue;
98	    }
99	    if (name.replace(/\.json$/, "") !== b.runId) {
100	      out.skipped.push({ file, reason: `file name does not match its runId (${b.runId})` });
101	      continue;
102	    }
103	    out.bundles.push({ bundle: b, file });
104	  }
105	  return out;
106	}
107	
108	export interface GatherResult {
109	  bundles: Source[];
110	  skipped: { file: string; reason: string }[];
111	}
112	
113	/** Real bundles from the runs dir and the published dir, deduplicated by runId. */
114	export function gatherRealBundles(runsDir: string, webBundlesDir: string): GatherResult {
115	  const fromRuns = collectBundles(runsDir);
116	  const fromWeb = publishedBundles(webBundlesDir);
117	  const skipped = [
118	    ...fromRuns.skipped.map((s) => ({ file: `core/runs/${s.file}`, reason: s.reason })),
119	    ...fromRuns.excluded.map((s) => ({ file: `core/runs/${s.file}`, reason: s.reason })),
120	    ...fromWeb.skipped,
121	  ];
122	  const byId = new Map<string, Source>();
123	  for (const s of [...fromRuns.bundles.map((c) => ({ bundle: c.bundle, file: `core/runs/${c.file}` })), ...fromWeb.bundles]) {
124	    if (isDriftReplay(s.bundle)) {
125	      skipped.push({ file: s.file, reason: "DRIFT FIXTURE replay (altered recording) — never a cost or safety source" });
126	      continue;
127	    }
128	    const prior = byId.get(s.bundle.runId);
129	    if (!prior) byId.set(s.bundle.runId, s);
130	    else if (prior.bundle.contentHash !== s.bundle.contentHash)
131	      skipped.push({ file: s.file, reason: `same runId as ${prior.file} with a different content hash; the first copy is used` });
132	  }
133	  const bundles = [...byId.values()].sort((x, y) => Date.parse(x.bundle.startedAt) - Date.parse(y.bundle.startedAt) || (x.bundle.runId < y.bundle.runId ? -1 : 1));
134	  skipped.sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : 0));
135	  return { bundles, skipped };
136	}
137	
138	function readCertificates(path: string): { report: CertificateReport | null; ref: { file: string; sha256: string } | null } {
139	  if (!existsSync(path)) return { report: null, ref: null };
140	  const text = readFileSync(path, "utf8");
141	  const parsed = CertificateReportSchema.safeParse(JSON.parse(text));
142	  if (!parsed.success || parsed.data.sample) return { report: null, ref: null };
143	  return { report: parsed.data, ref: { file: "web/public/certificates/report.json", sha256: sha256Hex(canonicalJson(parsed.data)) } };
144	}
145	
146	/** Assemble the file body from gathered inputs (pure; exported for tests). */
147	export function buildEconomicsBody(input: {
148	  bundles: readonly Source[];
149	  skipped: readonly { file: string; reason: string }[];
150	  certificates: CertificateReport | null;
151	  certificatesRef: { file: string; sha256: string } | null;
152	  plan: CfoPlan | null;
153	  planReason: string | null;
154	}): EconomicsBody {
155	  const { computed, computedReason } = computeEconomics({ bundles: input.bundles.map((s) => s.bundle), certificates: input.certificates });
156	  return {
157	    schemaVersion: 1,
158	    generatedBy: ECONOMICS_GENERATED_BY,
159	    sample: false,
160	    sources: {
161	      bundles: input.bundles.map((s) => ({ runId: s.bundle.runId, contentHash: s.bundle.contentHash, file: s.file })),
162	      skipped: [...input.skipped],
163	      certificatesReport: input.certificatesRef,
164	    },
165	    computed,
166	    computedReason,
167	    plan: input.plan,
168	    planReason: input.plan ? null : input.planReason ?? "No cfo.ai plan imported yet. Import your cfo.ai plan: pnpm notary economics --cfo-import <file>",
169	    combined: combine(computed, input.plan),
170	  };
171	}
172	
173	export interface WriteEconomicsOptions {
174	  runsDir?: string;
175	  webBundlesDir?: string;
176	  certificatesReport?: string;
177	  economicsJson?: string;
178	  /** null = do not write docs/BUSINESS.md. */
179	  businessMd?: string | null;
180	  /** null = do not write export/cfo-inputs.csv (the inputs sheet for cfo.ai). */
181	  cfoInputsCsv?: string | null;
182	  /** Path to a cfo.ai export in notary-cfo-plan-csv/1. */
183	  cfoImport?: string;
184	  now?: () => Date;
185	}
186	
187	export function writeEconomics(opts: WriteEconomicsOptions = {}): { file: EconomicsFile; lines: string[] } {
188	  const paths = { ...ECONOMICS_PATHS, ...Object.fromEntries(Object.entries(opts).filter(([, v]) => v !== undefined)) } as typeof ECONOMICS_PATHS & { businessMd: string | null; cfoInputsCsv: string | null };
189	  const lines: string[] = [];
190	  const gathered = gatherRealBundles(paths.runsDir, paths.webBundlesDir);
191	  const certs = readCertificates(paths.certificatesReport);
192	
193	  let plan: CfoPlan | null = null;
194	  let planReason: string | null = null;
195	  if (opts.cfoImport) {
