194	function sortEntries(entries: BundleIndexEntry[]): BundleIndexEntry[] {
195	  return entries.sort(
196	    (x, y) => Date.parse(x.startedAt) - Date.parse(y.startedAt) || (x.runId < y.runId ? -1 : x.runId > y.runId ? 1 : 0),
197	  );
198	}
