234	    const file = join(found.dir, `${id}.json`);
235	    if (!isInside(found.dir, file)) return c.json({ error: "invalid bundle id" }, 400);
236	    if (!existsSync(file)) return c.json({ error: `bundle ${id} is indexed but its file is missing` }, 404);
237	
238	    let raw: unknown;
239	    try {
240	      raw = JSON.parse(await readFile(file, "utf8"));
241	    } catch (err) {
242	      return c.json({ error: `bundle ${id} is not valid JSON: ${(err as Error).message}` }, 500);
243	    }
244	    const checked = verifyBundle(raw);
245	    if (checked.ok) return c.json(checked.bundle);
246	    if (checked.reason === "hash") {
