1	/**
2	 * Unit economics from REAL run bundles: pure, deterministic code over the bundles' own recorded
3	 * usage, credits and grader metrics. Same input, identical output (no clock, no environment, no
4	 * model). A figure that cannot be computed is null with the reason, never 0 as a stand-in.
5	 *
6	 * Rules (each also written into the output as `basis`, so the page can say how a number was made):
7	 *   - costs come from LIVE bundles only; a replay re-reads cassettes and spends nothing new, so
8	 *     counting it would understate the cost per run
9	 *   - Crustdata credits have no USD price (DECISIONS #167): credits and model USD stay separate
10	 *   - unsafe actions prevented = naive minus guarded `unsafe_actions_total` of the newest live
11	 *     naive and guarded queue runs of the same world (seed), summed over worlds
12	 *   - cost per notarized belief = all live notarize spend / distinct notarized beliefs in each
13	 *     tool's newest full notarize bundle (beliefs persist across runs, so they are not summed)
14	 *   - cost per certificate = the same spend / certified claims in public/certificates/report.json,
15	 *     only when every bundle that report counted is among the real bundles here (else stale)
16	 */
17	import { classify } from "../export/collect.js";
18	import type { CertificateReport } from "../schema/certificate.js";
19	import type { RunBundle, Tool } from "../schema/index.js";
20	import type {
21	  CfoPlan,
22	  EconomicsCombined,
23	  EconomicsComputed,
24	  EconomicsPair,
25	  EconomicsRatio,
26	  EconomicsRun,
27	  EconomicsTool,
28	} from "../schema/economics.js";
29	
30	const ROLES = ["executor", "reflector", "adversary"] as const;
31	const TOOLS: readonly Tool[] = ["crustdata", "dodo"];
32	
33	/** Sums of float USD rounded to 1e-9 so binary noise never reaches the file (still deterministic). */
34	const round = (n: number): number => Math.round(n * 1e9) / 1e9;
35	const sum = (xs: readonly number[]): number => round(xs.reduce((a, b) => a + b, 0));
36	
37	const byStart = (x: { startedAt: string; runId: string }, y: { startedAt: string; runId: string }): number =>
38	  Date.parse(x.startedAt) - Date.parse(y.startedAt) || (x.runId < y.runId ? -1 : x.runId > y.runId ? 1 : 0);
39	
40	const metric = (b: RunBundle, key: string): number | null => {
41	  const v = b.metrics[key];
42	  return typeof v === "number" && Number.isFinite(v) ? v : null;
43	};
44	
45	function notarizedIds(b: RunBundle): string[] {
46	  return [...new Set(b.beliefs.after.filter((x) => x.status === "notarized").map((x) => x.id))].sort();
47	}
48	
49	export function economicsRun(b: RunBundle): EconomicsRun {
50	  if (b.kind === "sample" || b.variant === "sample" || b.sample) throw new Error(`economicsRun: ${b.runId} is a sample bundle`);
51	  const usdByRole = { executor: round(b.usageByRole.executor.usd), reflector: round(b.usageByRole.reflector.usd), adversary: round(b.usageByRole.adversary.usd) };
52	  const creditsByEndpoint = Object.fromEntries(Object.entries(b.credits.byEndpoint).sort(([a], [c]) => (a < c ? -1 : a > c ? 1 : 0)));
53	  return {
54	    runId: b.runId,
55	    contentHash: b.contentHash,
56	    kind: b.kind,
57	    variant: b.variant as EconomicsRun["variant"],
58	    mode: b.mode,
59	    tool: b.tool ?? null,
60	    seed: b.seed,
61	    startedAt: b.startedAt,
62	    status: b.status,
63	    modelUsd: sum(ROLES.map((r) => usdByRole[r])),
64	    usdByRole,
65	    tokens: ROLES.reduce((n, r) => n + b.usageByRole[r].inputTokens + b.usageByRole[r].outputTokens, 0),
66	    credits: round(b.credits.total),
67	    creditsByEndpoint,
68	    unsafeActions: b.kind === "run" ? metric(b, "unsafe_actions_total") : null,
69	    holds: b.kind === "run" ? metric(b, "holds") : null,
70	    beliefsNotarized: b.kind === "notarize" ? notarizedIds(b).length : null,
71	  };
72	}
73	
74	function ratio(usdTotal: number, creditsTotal: number, denominator: number | null, basis: string, reasonIfNone: string): EconomicsRatio {
75	  if (denominator === null || denominator === 0) return { usd: null, credits: null, basis, reason: reasonIfNone };
76	  return { usd: round(usdTotal / denominator), credits: round(creditsTotal / denominator), basis, reason: null };
77	}
78	
79	export interface ComputeInput {
80	  /** Verified, real (sample:false) run/notarize bundles. Drift fixtures must already be removed. */
81	  bundles: readonly RunBundle[];
82	  /** public/certificates/report.json when it exists and is real; null otherwise. */
83	  certificates: CertificateReport | null;
84	}
85	
86	/** null + reason when there are no real bundles; otherwise every computed figure. */
87	export function computeEconomics(input: ComputeInput): { computed: EconomicsComputed | null; computedReason: string | null } {
88	  const bundles = [...input.bundles].sort(byStart);
89	  for (const b of bundles) if (b.sample || b.kind === "sample") throw new Error(`computeEconomics: ${b.runId} is a sample bundle; fixtures are never a source`);
90	  if (!bundles.length)
91	    return {
92	      computed: null,
93	      computedReason:
94	        "No real run bundles yet (sample:false). Run `pnpm notary notarize --tool dodo` and `pnpm notary run --queue …` live, then `pnpm notary economics`. Fixture runs are never counted.",
95	    };
96	
97	  const runs = bundles.map(economicsRun);
98	  const live = runs.filter((r) => r.mode === "live");
99	  const liveBundles = bundles.filter((b) => b.mode === "live");
100	
101	  const usdByRole = { executor: sum(live.map((r) => r.usdByRole.executor)), reflector: sum(live.map((r) => r.usdByRole.reflector)), adversary: sum(live.map((r) => r.usdByRole.adversary)) };
102	  const endpoints = [...new Set(live.flatMap((r) => Object.keys(r.creditsByEndpoint)))].sort();
103	  const creditsByEndpoint = Object.fromEntries(endpoints.map((e) => [e, sum(live.map((r) => r.creditsByEndpoint[e] ?? 0))]));
104	  const totals = {
105	    runs: runs.length,
106	    liveRuns: live.length,
107	    replayRuns: runs.length - live.length,
108	    modelUsd: sum(live.map((r) => r.modelUsd)),
109	    credits: sum(live.map((r) => r.credits)),
110	    tokens: live.reduce((n, r) => n + r.tokens, 0),
111	  };
112	
113	  const costPerRun = ratio(
114	    totals.modelUsd,
115	    totals.credits,
116	    live.length,
117	    "Model USD (executor + reflector + adversary) and Crustdata credits summed over live real bundles, divided by the number of live bundles. Replays are excluded: they spend nothing new.",
118	    "No live real bundle yet: replays spend nothing, so there is no cost per run to show.",
119	  );
120	
121	  // --- notarize spend per tool and what it bought
122	  const certByTool = new Map<Tool, number>();
123	  let certReason: string | null = null;
124	  if (!input.certificates) certReason = "No real certificates report (public/certificates/report.json). Run `pnpm notary export --certificates`.";
125	  else if (input.certificates.sample) certReason = "The certificates report is fixture data and is never counted.";
126	  else {
127	    const have = new Set(bundles.map((b) => `${b.runId}@${b.contentHash}`));
128	    const counted = new Set(input.certificates.sourceBundles.map((s) => `${s.runId}@${s.contentHash}`));
129	    const missing = input.certificates.sourceBundles.filter((s) => !have.has(`${s.runId}@${s.contentHash}`));
130	    // The newest full notarize bundle of each tool is what certificates are issued from; a report
131	    // that did not count it predates it.
132	    const newer = TOOLS.flatMap((tool) => {
133	      const newest = bundles.filter((b) => b.kind === "notarize" && b.tool === tool && classify(b) === "notarize-full").at(-1);
134	      return newest && !counted.has(`${newest.runId}@${newest.contentHash}`) ? [newest.runId] : [];
135	    });
136	    if (missing.length)
137	      certReason = `The certificates report counted bundles that are not among the real bundles here (${missing.map((m) => m.runId).join(", ")}). Re-run \`pnpm notary export --certificates\`.`;
138	    else if (newer.length)
139	      certReason = `The certificates report predates ${newer.join(", ")}. Re-run \`pnpm notary export --certificates\`, then \`pnpm notary economics\`.`;
140	    else for (const t of input.certificates.tools) certByTool.set(t.tool, t.counts.certified);
141	  }
142	
143	  const tools: EconomicsTool[] = TOOLS.flatMap((tool) => {
144	    const own = liveBundles.filter((b) => b.kind === "notarize" && b.tool === tool);
145	    const fulls = bundles.filter((b) => b.kind === "notarize" && b.tool === tool && classify(b) === "notarize-full");
146	    const newest = fulls[fulls.length - 1];
147	    const certified = certReason === null ? certByTool.get(tool) ?? 0 : null;
148	    if (!own.length && !newest && !certified) return [];
149	    const modelUsd = sum(own.map((b) => economicsRun(b).modelUsd));
150	    return [
151	      {
152	        tool,
153	        runs: own.length,
154	        modelUsd,
155	        credits: sum(own.map((b) => b.credits.total)),
156	        notarizedBeliefs: newest ? notarizedIds(newest).length : null,
157	        certified,
158	        costPerCertificateUsd: certified ? round(modelUsd / certified) : null,
159	      },
160	    ];
161	  });
162	  const notarizeUsd = sum(tools.map((t) => t.modelUsd));
163	  const notarizeCredits = sum(tools.map((t) => t.credits));
164	  const notarizeRuns = tools.reduce((n, t) => n + t.runs, 0);
165	  const beliefs = tools.some((t) => t.notarizedBeliefs !== null) ? tools.reduce((n, t) => n + (t.notarizedBeliefs ?? 0), 0) : null;
166	
167	  const costPerNotarizedBelief = ratio(
168	    notarizeUsd,
169	    notarizeCredits,
170	    notarizeRuns ? beliefs : null,
171	    "Model USD and credits of every live notarize bundle, divided by the distinct notarized beliefs in each tool's newest full notarize bundle (beliefs persist across runs, so they are counted once).",
172	    !notarizeRuns ? "No live notarize bundle yet." : beliefs === null ? "No full notarize bundle yet, so no belief has been notarized." : "No belief is notarized yet.",
173	  );
174	
175	  const certified = certReason === null ? [...certByTool.values()].reduce((a, b) => a + b, 0) : null;
176	  const costPerCertificate = ratio(
177	    notarizeUsd,
178	    notarizeCredits,
179	    notarizeRuns ? certified : null,
180	    "The same live notarize spend, divided by the certified claims in public/certificates/report.json (only when that report counted exactly bundles found here).",
181	    certReason ?? (!notarizeRuns ? "No live notarize bundle yet." : "No certificate is issued yet (certified = 0)."),
182	  );
183	
184	  // --- naive vs guarded: prevented and held, per world (seed), newest live pair
185	  const queueRuns = liveBundles.filter((b) => b.kind === "run" && (b.variant === "naive" || b.variant === "guarded"));
186	  const seeds = [...new Set(queueRuns.map((b) => b.seed))].sort((a, b) => a - b);
187	  const pairs: EconomicsPair[] = seeds.flatMap((seed) => {
188	    const world = queueRuns.filter((b) => b.seed === seed);
189	    const naive = world.filter((b) => b.variant === "naive").at(-1);
190	    const guarded = world.filter((b) => b.variant === "guarded").at(-1);
191	    if (!naive || !guarded) return [];
192	    const naiveUnsafe = metric(naive, "unsafe_actions_total");
193	    const guardedUnsafe = metric(guarded, "unsafe_actions_total");
194	    return [
195	      {
196	        seed,
197	        naiveRunId: naive.runId,
198	        guardedRunId: guarded.runId,
199	        naiveUnsafe,
200	        guardedUnsafe,
201	        prevented: naiveUnsafe !== null && guardedUnsafe !== null ? naiveUnsafe - guardedUnsafe : null,
202	        held: metric(guarded, "holds"),
203	      },
204	    ];
205	  });
206	  const prevented = pairs.filter((p) => p.prevented !== null);
207	  const held = pairs.filter((p) => p.held !== null);
208	  const noPair = "No world has both a live naive and a live guarded queue run yet. Run `pnpm notary run --queue <file> --naive` and `pnpm notary run --queue <file>` with the same seed.";
209	
210	  return {
211	    computedReason: null,
212	    computed: {
213	      runs,
214	      totals,
215	      usdByRole,
216	      creditsByEndpoint,
217	      costPerRun,
218	      costPerNotarizedBelief,
219	      costPerCertificate,
220	      tools,
221	      pairs,
222	      unsafeActionsPrevented: {
223	        value: prevented.length ? prevented.reduce((n, p) => n + p.prevented!, 0) : null,
224	        basis: "Grader `unsafe_actions_total`, naive minus guarded, newest live pair per world (seed), summed over worlds.",
225	        reason: prevented.length ? null : pairs.length ? "The grader could not establish ground truth for any pair (unsafe_actions_total is null)." : noPair,
226	      },
227	      heldActions: {
228	        value: held.length ? held.reduce((n, p) => n + p.held!, 0) : null,
229	        basis: "Grader `holds` of the guarded run in each pair: money actions held for a person instead of executed.",
230	        reason: held.length ? null : pairs.length ? "The guarded runs recorded no holds metric." : noPair,
231	      },
232	    },
233	  };
234	}
235	
236	/**
237	 * Figures that need both sources. Only one today: unsafe actions prevented (computed) × the plan's
238	 * `cost_per_incident` figure (as exported). null unless both exist.
239	 */
240	export function combine(computed: EconomicsComputed | null, plan: CfoPlan | null): EconomicsCombined {
241	  const prevented = computed?.unsafeActionsPrevented.value ?? null;
242	  const perIncident = plan?.figures.find((f) => f.key === "cost_per_incident");
243	  if (prevented === null || !perIncident) return { incidentsPreventedValue: null };
244	  return {
245	    incidentsPreventedValue: {
246	      value: round(prevented * perIncident.value),
247	      unit: perIncident.unit,
248	      basis: `${prevented} unsafe actions prevented (grader, real runs) × cost per incident ${perIncident.value} ${perIncident.unit} (cfo.ai plan, "${perIncident.label}").`,
249	    },
250	  };
251	}
